function latex_text = render_latex_table(output_file, table_content, options)
% RENDER_LATEX_TABLE  Write generated LaTeX table content to a file.

    arguments
        output_file (1,:) char
        table_content
        options.generated_by (1,:) char = ''
        options.header_lines (1,:) cell = {}
    end

    content_text = normalize_content(table_content);

    header_lines = {
        '% AUTO-GENERATED FILE. DO NOT EDIT MANUALLY.'
        sprintf('%% Generated: %s', char(datetime('now', 'Format', 'yyyy-MM-dd HH:mm:ss')))
    };

    if ~isempty(options.generated_by)
        header_lines{end + 1} = sprintf('%% Generated by: %s', options.generated_by);
    end

    if ~isempty(options.header_lines)
        header_lines = [header_lines(:); options.header_lines(:)]; %#ok<AGROW>
    end

    latex_text = strjoin([header_lines(:); {''}; {content_text}], newline);
    if ~endsWith(latex_text, newline)
        latex_text = [latex_text newline]; %#ok<AGROW>
    end

    output_dir = fileparts(output_file);
    if ~isempty(output_dir) && ~exist(output_dir, 'dir')
        mkdir(output_dir);
    end

    temp_file = [tempname(output_dir) '.tex'];
    file_id = fopen(temp_file, 'w');
    if file_id == -1
        error('Could not open temporary file for writing: %s', temp_file);
    end

    try
        fwrite(file_id, latex_text, 'char');
        fclose(file_id);

        if exist(output_file, 'file')
            delete(output_file);
        end

        movefile(temp_file, output_file, 'f');
    catch write_error
        fclose_if_open(file_id);
        if exist(temp_file, 'file')
            delete(temp_file);
        end
        rethrow(write_error);
    end
end

function text = normalize_content(table_content)
    if ischar(table_content)
        text = table_content;
        return;
    end

    if isstring(table_content)
        text = strjoin(cellstr(table_content(:)'), newline);
        return;
    end

    if iscell(table_content)
        text = strjoin(table_content, newline);
        return;
    end

    error('table_content must be char, string, or cell array of lines.');
end

function fclose_if_open(file_id)
    if isnumeric(file_id) && isscalar(file_id) && file_id > 0
        try
            fclose(file_id);
        catch
        end
    end
end